insert into exercise_pool (slug, names, instructions, aliases, match_keys, category, movement_pattern, primary_muscles, secondary_muscles, tertiary_muscles, equipment, is_unilateral, long_length, dose_unit, default_rep_min, default_rep_max, default_rest_sec, tags, image_url, image_urls, image_license, image_attribution) values
  ('ab_wheel_rollout', $json${"ru": "Ролик для пресса", "en": "Ab Wheel Rollout", "pt": "Rolo abdominal", "es": "Rueda abdominal", "fr": "Roulette abdominale"}$json$::jsonb, $json${"ru": "С коленей, таз подкручен. Раскатывайся ровно настолько, насколько удерживаешь поясницу от прогиба. Возвращайся прессом, а не руками.", "en": "From the knees with the pelvis tucked. Roll out only as far as you can keep the lower back from arching. Pull back with the abs, not the arms."}$json$::jsonb, array['колесо для пресса', 'раскатка ролика', 'ab rollout']::text[], array['ab rollout', 'ab wheel rollout', 'rolo abdominal', 'roulette abdominale', 'rueda abdominal', 'колесо для пресса', 'раскатка ролика', 'ролик для пресса']::text[], 'core', 'core', array['abs']::text[], array['obliques', 'lats']::text[], array['front_delts', 'lower_back']::text[], array['other', 'bodyweight']::text[], false, false, 'reps', 6, 12, 75, array['home', 'gym']::text[], null, '{}'::text[], null, null),
  ('air_squat', $json${"ru": "Приседания без веса", "en": "Bodyweight Squat", "pt": "Agachamento livre", "es": "Sentadilla sin peso", "fr": "Squat au poids du corps"}$json$::jsonb, $json${"ru": "Стопы на ширине плеч, руки вперёд для противовеса. Садись до параллели или ниже, пятки от пола не отрывай. Первое упражнение, с которого стоит начинать любому новичку.", "en": "Feet shoulder width, arms forward as a counterweight. Sit to parallel or below with the heels down. The first squat anyone should learn."}$json$::jsonb, array['присед без веса', 'воздушный присед', 'приседания с собственным весом']::text[], array['agachamento livre', 'air squat', 'bodyweight squat', 'sentadilla sin peso', 'squat au poids du corps', 'воздушный присед', 'присед без веса', 'приседания без веса', 'приседания с собственным весом']::text[], 'compound', 'squat', array['quads', 'glutes']::text[], array['hamstrings', 'adductors']::text[], array['abs', 'calves']::text[], array['bodyweight']::text[], false, false, 'reps', 12, 20, 60, array['home', 'bodyweight', 'beginner_safe']::text[], null, '{}'::text[], null, null),
  ('arnold_press', $json${"ru": "Жим Арнольда", "en": "Arnold Press", "pt": "Desenvolvimento Arnold", "es": "Press Arnold", "fr": "Développé Arnold"}$json$::jsonb, $json${"ru": "Старт с ладонями к себе у груди. По ходу подъёма разворачивай кисти наружу, наверху ладони смотрят вперёд. Вес меньше обычного жима.", "en": "Start with the palms facing you at chest level. Rotate the hands outward as you press so the palms face forward at the top. Lighter than a straight press."}$json$::jsonb, array['арнольд пресс', 'жим арнольда с гантелями', 'arnold']::text[], array['arnold', 'arnold press', 'desenvolvimento arnold', 'développé arnold', 'press arnold', 'арнольд пресс', 'жим арнольда', 'жим арнольда с гантелями']::text[], 'compound', 'vertical_push', array['front_delts']::text[], array['side_delts', 'triceps']::text[], array['upper_back']::text[], array['dumbbell', 'bench']::text[], false, false, 'reps', 10, 12, 90, array['gym']::text[], null, '{}'::text[], null, null),
  ('assisted_pull_up', $json${"ru": "Подтягивания в гравитроне", "en": "Assisted Pull-Up", "pt": "Barra assistida", "es": "Dominadas asistidas", "fr": "Tractions assistées"}$json$::jsonb, $json${"ru": "Противовес подбирается так, чтобы последние два повторения давались тяжело. Уменьшай его по мере прогресса, а не увеличивай число повторений бесконечно.", "en": "Set the counterweight so the last two reps are hard. Reduce the assistance as you progress instead of endlessly adding reps."}$json$::jsonb, array['гравитрон', 'подтягивания с противовесом', 'assisted chin up']::text[], array['assisted chin up', 'assisted pull up', 'barra assistida', 'dominadas asistidas', 'tractions assistées', 'гравитрон', 'подтягивания в гравитроне', 'подтягивания с противовесом']::text[], 'compound', 'vertical_pull', array['lats']::text[], array['biceps', 'upper_back']::text[], '{}'::text[], array['machine']::text[], false, false, 'reps', 8, 12, 120, array['gym', 'beginner_safe', 'machine_friendly']::text[], null, '{}'::text[], null, null),
  ('back_extension', $json${"ru": "Гиперэкстензия", "en": "Back Extension", "pt": "Extensão lombar", "es": "Hiperextensiones", "fr": "Extension lombaire"}$json$::jsonb, $json${"ru": "Подушка чуть ниже тазовых косточек. Опускайся до натяжения задней поверхности и поднимайся до прямой линии, не переразгибаясь назад.", "en": "Pad just below the hip bones. Lower until you feel the hamstrings, rise to a straight line and do not hyperextend past it."}$json$::jsonb, array['гиперэкстензии', 'разгибания спины', 'hyperextension']::text[], array['back extension', 'extension lombaire', 'extensão lombar', 'hiperextensiones', 'hyperextension', 'гиперэкстензии', 'гиперэкстензия', 'разгибания спины']::text[], 'isolation', 'hinge', array['lower_back']::text[], array['glutes', 'hamstrings']::text[], '{}'::text[], array['machine', 'bodyweight']::text[], false, true, 'reps', 12, 15, 60, array['gym', 'back_friendly']::text[], '/exercises/back_extension-1.webp', array['/exercises/back_extension-1.webp', '/exercises/back_extension-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('band_chest_fly', $json${"ru": "Сведения с резиной", "en": "Band Chest Fly", "pt": "Crucifixo com elástico", "es": "Aperturas de pecho con banda", "fr": "Écarté pectoraux à l'élastique"}$json$::jsonb, $json${"ru": "Лента закреплена за спиной на уровне груди. Своди руки перед собой по дуге, сопротивление растёт к концу движения.", "en": "Band anchored behind you at chest height. Bring the hands together along an arc; the resistance peaks at the end."}$json$::jsonb, array['сведение рук с резиной', 'разводка с эспандером']::text[], array['aperturas de pecho con banda', 'band chest fly', 'crucifixo com elástico', 'écarté pectoraux à l''élastique', 'разводка с эспандером', 'сведение рук с резиной', 'сведения с резиной']::text[], 'isolation', 'isolation', array['chest']::text[], array['front_delts']::text[], array['abs']::text[], array['resistance_band']::text[], false, false, 'reps', 15, 20, 45, array['home']::text[], '/exercises/band_chest_fly-1.webp', array['/exercises/band_chest_fly-1.webp', '/exercises/band_chest_fly-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('band_pull_apart', $json${"ru": "Разведение резины перед собой", "en": "Band Pull-Apart", "pt": "Abertura com elástico", "es": "Aperturas con banda elástica", "fr": "Écarté à l'élastique"}$json$::jsonb, $json${"ru": "Руки прямые на уровне груди. Растягивай ленту в стороны до касания груди, лопатки сводятся. Хорошо идёт в разминку перед жимами.", "en": "Straight arms at chest height. Stretch the band out until it touches the chest, letting the shoulder blades come together. Good as a warm-up before pressing."}$json$::jsonb, array['разведение резинки', 'растягивание резины', 'pull apart']::text[], array['abertura com elástico', 'aperturas con banda elástica', 'band pull apart', 'pull apart', 'écarté à l''élastique', 'разведение резинки', 'разведение резины перед собой', 'растягивание резины']::text[], 'isolation', 'isolation', array['rear_delts']::text[], array['upper_back', 'rotator_cuff']::text[], '{}'::text[], array['resistance_band']::text[], false, false, 'reps', 15, 25, 45, array['home', 'warmup', 'shoulder_health']::text[], null, '{}'::text[], null, null),
  ('band_row', $json${"ru": "Тяга резины сидя", "en": "Seated Band Row", "pt": "Remada sentada com elástico", "es": "Remo sentado con banda", "fr": "Rowing assis à l'élastique"}$json$::jsonb, $json${"ru": "Лента вокруг стоп, сиди с прямой спиной. Тяни к животу, сводя лопатки. Единственная нормальная тяга, когда рядом нет ни зала, ни турника.", "en": "Band around the feet, sitting tall. Pull to the abdomen and squeeze the shoulder blades. The one workable row when there is no gym and no bar."}$json$::jsonb, array['тяга с резинкой', 'тяга эспандера сидя']::text[], array['band row', 'remada sentada com elástico', 'remo sentado con banda', 'rowing assis à l''élastique', 'seated band row', 'тяга резины сидя', 'тяга с резинкой', 'тяга эспандера сидя']::text[], 'compound', 'horizontal_pull', array['upper_back']::text[], array['lats', 'biceps', 'rear_delts']::text[], '{}'::text[], array['resistance_band']::text[], false, false, 'reps', 12, 20, 60, array['home', 'beginner_safe']::text[], null, '{}'::text[], null, null),
  ('band_squat', $json${"ru": "Приседания с резиной", "en": "Band Squat", "pt": "Agachamento com elástico", "es": "Sentadilla con banda", "fr": "Squat à l'élastique"}$json$::jsonb, $json${"ru": "Встань на ленту, второй конец через плечи. Сопротивление растёт к верхней точке, поэтому внизу движение лёгкое, а вставать тяжело.", "en": "Stand on the band with the other end over your shoulders. Resistance builds toward the top, so the bottom is easy and standing up is the hard part."}$json$::jsonb, array['присед с резинкой', 'приседания с эспандером']::text[], array['agachamento com elástico', 'band squat', 'sentadilla con banda', 'squat à l''élastique', 'присед с резинкой', 'приседания с резиной', 'приседания с эспандером']::text[], 'compound', 'squat', array['quads', 'glutes']::text[], array['adductors']::text[], array['abs']::text[], array['resistance_band']::text[], false, false, 'reps', 12, 20, 60, array['home', 'beginner_safe']::text[], null, '{}'::text[], null, null),
  ('bb_back_squat', $json${"ru": "Приседания со штангой", "en": "Barbell Back Squat", "pt": "Agachamento com barra", "es": "Sentadilla con barra", "fr": "Squat à la barre"}$json$::jsonb, $json${"ru": "Гриф на верху трапеций, стопы чуть шире плеч, носки слегка наружу. Садись между ног, колени идут по направлению носков. Глубина — до параллели бедра с полом или ниже, если позволяет подвижность.", "en": "Bar on the upper traps, feet a bit wider than shoulders, toes turned slightly out. Sit between your feet with the knees tracking over the toes. Depth to parallel or below if your mobility allows."}$json$::jsonb, array['приседания со штангой на спине', 'back squat']::text[], array['agachamento com barra', 'back squat', 'barbell back squat', 'bb back squat', 'sentadilla con barra', 'squat à la barre', 'приседания со штангой', 'приседания со штангой на спине']::text[], 'compound', 'squat', array['quads', 'glutes']::text[], array['hamstrings', 'adductors', 'lower_back']::text[], array['abs', 'calves']::text[], array['barbell']::text[], false, true, 'reps', 5, 8, 180, array['gym', 'barbell_lift']::text[], '/exercises/bb_back_squat-1.webp', array['/exercises/bb_back_squat-1.webp', '/exercises/bb_back_squat-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('bb_bench_press', $json${"ru": "Жим штанги лёжа", "en": "Barbell Bench Press", "pt": "Supino reto com barra", "es": "Press de banca con barra", "fr": "Développé couché à la barre"}$json$::jsonb, $json${"ru": "Лопатки сведены и прижаты к скамье, стопы плотно на полу. Опусти штангу к нижней части груди, локти под углом около 45 градусов к корпусу. Жми вверх, не отрывая таз от скамьи.", "en": "Shoulder blades pinched and pressed into the bench, feet flat. Lower the bar to the lower chest with elbows about 45 degrees from the torso. Press up without lifting your hips."}$json$::jsonb, array['жим лёжа', 'жим штанги', 'bench press', 'flat bench']::text[], array['barbell bench press', 'bb bench press', 'bench press', 'développé couché à la barre', 'flat bench', 'press de banca con barra', 'supino reto com barra', 'жим лежа', 'жим штанги', 'жим штанги лежа']::text[], 'compound', 'horizontal_push', array['chest']::text[], array['triceps', 'front_delts']::text[], array['upper_back']::text[], array['barbell', 'bench']::text[], false, false, 'reps', 5, 8, 180, array['gym', 'barbell_lift']::text[], '/exercises/bb_bench_press-1.webp', array['/exercises/bb_bench_press-1.webp', '/exercises/bb_bench_press-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('bb_bent_over_row', $json${"ru": "Тяга штанги в наклоне", "en": "Barbell Bent-Over Row", "pt": "Remada curvada com barra", "es": "Remo con barra", "fr": "Rowing barre buste penché"}$json$::jsonb, $json${"ru": "Наклон корпуса около 45 градусов, спина прямая, колени слегка согнуты. Тяни штангу к низу живота, локти вдоль корпуса. Не выпрямляйся рывком.", "en": "Hinge to about 45 degrees with a flat back and soft knees. Row the bar to the lower abdomen with the elbows tracking along the torso. Do not jerk upright."}$json$::jsonb, array['тяга штанги', 'тяга в наклоне', 'barbell row', 'bent over row']::text[], array['barbell bent over row', 'barbell row', 'bb bent over row', 'bent over row', 'remada curvada com barra', 'remo con barra', 'rowing barre buste penché', 'тяга в наклоне', 'тяга штанги', 'тяга штанги в наклоне']::text[], 'compound', 'horizontal_pull', array['upper_back', 'lats']::text[], array['biceps', 'rear_delts']::text[], array['lower_back', 'hamstrings', 'forearms']::text[], array['barbell']::text[], false, false, 'reps', 6, 10, 150, array['gym', 'barbell_lift']::text[], null, '{}'::text[], null, null),
  ('bb_overhead_press', $json${"ru": "Жим штанги стоя", "en": "Standing Barbell Overhead Press", "pt": "Desenvolvimento militar com barra", "es": "Press militar de pie", "fr": "Développé militaire debout"}$json$::jsonb, $json${"ru": "Гриф лежит на передних дельтах, хват чуть шире плеч. Сожми ягодицы и пресс, чтобы не прогибать поясницу. Убери голову назад и проведи штангу над макушкой.", "en": "Bar resting on the front delts, grip just wider than shoulders. Brace the glutes and abs so the lower back does not arch. Move the head back and press the bar over the crown."}$json$::jsonb, array['армейский жим', 'жим стоя', 'жим над головой', 'overhead press', 'ohp', 'military press']::text[], array['bb overhead press', 'desenvolvimento militar com barra', 'développé militaire debout', 'military press', 'ohp', 'overhead press', 'press militar de pie', 'standing barbell overhead press', 'армейский жим', 'жим над головой', 'жим стоя', 'жим штанги стоя']::text[], 'compound', 'vertical_push', array['front_delts']::text[], array['side_delts', 'triceps']::text[], array['upper_back', 'abs', 'traps']::text[], array['barbell']::text[], false, false, 'reps', 5, 8, 150, array['gym', 'barbell_lift']::text[], null, '{}'::text[], null, null),
  ('bb_shrug', $json${"ru": "Шраги со штангой", "en": "Barbell Shrug", "pt": "Encolhimento com barra", "es": "Encogimientos con barra", "fr": "Shrug à la barre"}$json$::jsonb, $json${"ru": "Поднимай плечи строго вверх, к ушам, без вращения. Задержись наверху на секунду и опусти полностью.", "en": "Shrug the shoulders straight up toward the ears with no rolling. Hold a second at the top and lower all the way."}$json$::jsonb, array['шраги', 'шраги со штангой', 'shrugs']::text[], array['barbell shrug', 'bb shrug', 'encogimientos con barra', 'encolhimento com barra', 'shrug à la barre', 'shrugs', 'шраги', 'шраги со штангой']::text[], 'isolation', 'isolation', array['traps']::text[], array['upper_back']::text[], array['forearms']::text[], array['barbell']::text[], false, false, 'reps', 10, 15, 75, array['gym']::text[], '/exercises/bb_shrug-1.webp', array['/exercises/bb_shrug-1.webp', '/exercises/bb_shrug-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('bb_upright_row', $json${"ru": "Протяжка со штангой", "en": "Barbell Upright Row", "pt": "Remada alta com barra", "es": "Remo al mentón con barra", "fr": "Rowing menton à la barre"}$json$::jsonb, $json${"ru": "Хват шире плеч, тяни до уровня груди, не выше. Если в плече щёлкает или тянет, замени махами.", "en": "Grip wider than shoulders and pull only to chest height. If the shoulder pinches, swap it for lateral raises."}$json$::jsonb, array['тяга штанги к подбородку', 'протяжка штангой']::text[], array['barbell upright row', 'bb upright row', 'remada alta com barra', 'remo al mentón con barra', 'rowing menton à la barre', 'протяжка со штангой', 'протяжка штангой', 'тяга штанги к подбородку']::text[], 'compound', 'vertical_pull', array['side_delts']::text[], array['traps', 'biceps']::text[], '{}'::text[], array['barbell']::text[], false, false, 'reps', 10, 15, 75, array['gym']::text[], '/exercises/bb_upright_row-1.webp', array['/exercises/bb_upright_row-1.webp', '/exercises/bb_upright_row-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('bench_dip', $json${"ru": "Обратные отжимания от скамьи", "en": "Bench Dip", "pt": "Mergulho no banco", "es": "Fondos en banco", "fr": "Dips sur banc"}$json$::jsonb, $json${"ru": "Ладони на краю скамьи, таз идёт вплотную вдоль неё. Опускайся до угла 90 градусов в локте, не глубже — плечи этого не любят.", "en": "Palms on the edge of the bench, hips travelling close to it. Descend to about 90 degrees at the elbow and no deeper; the shoulders do not like it."}$json$::jsonb, array['обратные отжимания', 'трицепсовые отжимания от скамьи', 'reverse push up']::text[], array['bench dip', 'dips sur banc', 'fondos en banco', 'mergulho no banco', 'reverse push up', 'обратные отжимания', 'обратные отжимания от скамьи', 'трицепсовые отжимания от скамьи']::text[], 'compound', 'horizontal_push', array['triceps']::text[], array['front_delts', 'chest']::text[], '{}'::text[], array['bench', 'bodyweight']::text[], false, false, 'reps', 10, 20, 60, array['home', 'bodyweight']::text[], '/exercises/bench_dip-1.webp', array['/exercises/bench_dip-1.webp', '/exercises/bench_dip-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('bent_over_cable_lateral_raise', $json${"ru": "Разведение на блоках в наклоне", "en": "Bent-Over Cable Lateral Raise", "pt": "Crucifixo inverso no cabo", "es": "Pájaros en polea", "fr": "Oiseau à la poulie"}$json$::jsonb, $json${"ru": "Тросы перекрещены перед корпусом, наклон вперёд. Разводи руки назад по дуге, нагрузка ровная по всей амплитуде.", "en": "Cables crossed in front of you, torso hinged forward. Sweep the arms back along an arc with even tension throughout."}$json$::jsonb, array['задние дельты на блоках', 'разводка в наклоне на блоке']::text[], array['bent over cable lateral raise', 'crucifixo inverso no cabo', 'oiseau à la poulie', 'pájaros en polea', 'задние дельты на блоках', 'разведение на блоках в наклоне', 'разводка в наклоне на блоке']::text[], 'isolation', 'isolation', array['rear_delts']::text[], array['upper_back']::text[], array['traps']::text[], array['cable_crossover', 'cable']::text[], false, false, 'reps', 12, 20, 60, array['gym', 'shoulder_health']::text[], '/exercises/bent_over_cable_lateral_raise-1.webp', array['/exercises/bent_over_cable_lateral_raise-1.webp', '/exercises/bent_over_cable_lateral_raise-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('bent_over_db_reverse_fly', $json${"ru": "Разводка гантелей в наклоне", "en": "Bent-Over Dumbbell Reverse Fly", "pt": "Crucifixo inverso com halteres", "es": "Pájaros con mancuernas", "fr": "Oiseau aux haltères"}$json$::jsonb, $json${"ru": "Наклонись почти параллельно полу, спина прямая. Разводи гантели в стороны локтями, а не кистями. Вес маленький.", "en": "Hinge to nearly parallel with a flat back. Open the dumbbells out by leading with the elbows, not the hands. Keep it light."}$json$::jsonb, array['разводка на задние дельты', 'махи в наклоне', 'rear delt fly']::text[], array['bent over db reverse fly', 'bent over dumbbell reverse fly', 'crucifixo inverso com halteres', 'oiseau aux haltères', 'pájaros con mancuernas', 'rear delt fly', 'махи в наклоне', 'разводка гантелей в наклоне', 'разводка на задние дельты']::text[], 'isolation', 'isolation', array['rear_delts']::text[], array['upper_back']::text[], array['lower_back', 'traps']::text[], array['dumbbell']::text[], false, false, 'reps', 12, 20, 60, array['gym', 'home', 'shoulder_health']::text[], null, '{}'::text[], null, null),
