  ('chest_dip', $json${"ru": "Отжимания на брусьях", "en": "Chest Dip", "pt": "Mergulho nas paralelas", "es": "Fondos en paralelas", "fr": "Dips aux barres parallèles"}$json$::jsonb, $json${"ru": "Наклони корпус вперёд и разведи локти чуть в стороны, чтобы нагрузка ушла в грудь. Опускайся до угла 90 градусов в локте, глубже только если плечи это позволяют.", "en": "Lean the torso forward and let the elbows travel slightly out to bias the chest. Descend to about 90 degrees at the elbow, deeper only if your shoulders allow."}$json$::jsonb, array['брусья', 'отжимания на брусьях с наклоном', 'dips']::text[], array['chest dip', 'dips', 'dips aux barres parallèles', 'fondos en paralelas', 'mergulho nas paralelas', 'брусья', 'отжимания на брусьях', 'отжимания на брусьях с наклоном']::text[], 'compound', 'horizontal_push', array['lower_chest']::text[], array['triceps', 'front_delts']::text[], array['abs']::text[], array['dip_bars', 'bodyweight']::text[], false, true, 'reps', 6, 12, 120, array['gym', 'bodyweight']::text[], '/exercises/chest_dip-1.webp', array['/exercises/chest_dip-1.webp', '/exercises/chest_dip-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
