  ('close_grip_bench_press', $json${"ru": "Жим лёжа узким хватом", "en": "Close-Grip Bench Press", "pt": "Supino com pegada fechada", "es": "Press de banca con agarre estrecho", "fr": "Développé couché prise serrée"}$json$::jsonb, $json${"ru": "Хват на ширине плеч, не уже — иначе страдают запястья. Локти идут близко к корпусу, гриф опускается к нижней части груди.", "en": "Grip at shoulder width, no narrower, or the wrists take it. Elbows stay close to the torso and the bar comes to the lower chest."}$json$::jsonb, array['узкий жим', 'жим узким хватом', 'close grip bench']::text[], array['close grip bench', 'close grip bench press', 'développé couché prise serrée', 'press de banca con agarre estrecho', 'supino com pegada fechada', 'жим лежа узким хватом', 'жим узким хватом', 'узкий жим']::text[], 'compound', 'horizontal_push', array['triceps']::text[], array['chest', 'front_delts']::text[], array['upper_back']::text[], array['barbell', 'bench']::text[], false, false, 'reps', 6, 10, 120, array['gym', 'barbell_lift']::text[], '/exercises/close_grip_bench_press-1.webp', array['/exercises/close_grip_bench_press-1.webp', '/exercises/close_grip_bench_press-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('close_grip_pulldown', $json${"ru": "Тяга верхнего блока узким хватом", "en": "Close-Grip Lat Pulldown", "pt": "Puxada com pegada fechada", "es": "Jalón con agarre estrecho", "fr": "Tirage vertical prise serrée"}$json$::jsonb, $json${"ru": "Параллельный или узкий хват. Тяни к низу груди, в конце сведи лопатки. Амплитуда длиннее, чем в широком хвате.", "en": "Neutral or narrow grip. Pull to the lower chest and squeeze the shoulder blades at the bottom. Longer range than the wide grip."}$json$::jsonb, array['тяга узким хватом', 'тяга параллельным хватом', 'close grip pulldown', 'v-bar pulldown']::text[], array['close grip lat pulldown', 'close grip pulldown', 'jalón con agarre estrecho', 'puxada com pegada fechada', 'tirage vertical prise serrée', 'v bar pulldown', 'тяга верхнего блока узким хватом', 'тяга параллельным хватом', 'тяга узким хватом']::text[], 'compound', 'vertical_pull', array['lats']::text[], array['biceps', 'upper_back']::text[], '{}'::text[], array['lat_pulldown', 'cable']::text[], false, false, 'reps', 8, 12, 120, array['gym']::text[], '/exercises/close_grip_pulldown-1.webp', array['/exercises/close_grip_pulldown-1.webp', '/exercises/close_grip_pulldown-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
