  ('conventional_deadlift', $json${"ru": "Становая тяга", "en": "Conventional Deadlift", "pt": "Levantamento terra", "es": "Peso muerto", "fr": "Soulevé de terre"}$json$::jsonb, $json${"ru": "Штанга над серединой стопы, плечи чуть впереди грифа. Спина прямая, грудь развёрнута. Тяни ногами от пола, штанга идёт вплотную к ногам, наверху не отклоняйся назад.", "en": "Bar over midfoot, shoulders slightly ahead of it. Flat back, chest set. Push the floor away with the legs, keeping the bar against the legs, and do not lean back at lockout."}$json$::jsonb, array['становая', 'тяга с пола', 'deadlift']::text[], array['conventional deadlift', 'deadlift', 'levantamento terra', 'peso muerto', 'soulevé de terre', 'становая', 'становая тяга', 'тяга с пола']::text[], 'compound', 'hinge', array['glutes', 'hamstrings']::text[], array['lower_back', 'quads']::text[], array['upper_back', 'traps', 'forearms', 'lats']::text[], array['barbell']::text[], false, true, 'reps', 3, 6, 210, array['gym', 'barbell_lift']::text[], '/exercises/conventional_deadlift-1.webp', array['/exercises/conventional_deadlift-1.webp', '/exercises/conventional_deadlift-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
