  ('db_bench_press', $json${"ru": "Жим гантелей лёжа", "en": "Dumbbell Bench Press", "pt": "Supino reto com halteres", "es": "Press de banca con mancuernas", "fr": "Développé couché aux haltères"}$json$::jsonb, $json${"ru": "Гантели на уровне груди, запястья над локтями. Опускай до лёгкого растяжения груди, не роняя плечи вперёд. В верхней точке не стукай гантели друг о друга, оставляй напряжение.", "en": "Dumbbells at chest level, wrists stacked over elbows. Lower until you feel a light stretch, keeping the shoulders back. Do not clang them at the top, keep tension."}$json$::jsonb, array['жим гантелей', 'жим гантель лёжа', 'dumbbell press', 'db bench']::text[], array['db bench', 'db bench press', 'dumbbell bench press', 'dumbbell press', 'développé couché aux haltères', 'press de banca con mancuernas', 'supino reto com halteres', 'жим гантелей', 'жим гантелей лежа', 'жим гантель лежа']::text[], 'compound', 'horizontal_push', array['chest']::text[], array['triceps', 'front_delts']::text[], array['upper_back']::text[], array['dumbbell', 'bench']::text[], false, true, 'reps', 8, 12, 120, array['gym']::text[], '/exercises/db_bench_press-1.webp', array['/exercises/db_bench_press-1.webp', '/exercises/db_bench_press-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('db_curl', $json${"ru": "Сгибание рук с гантелями", "en": "Dumbbell Curl", "pt": "Rosca alternada com halteres", "es": "Curl con mancuernas", "fr": "Curl aux haltères"}$json$::jsonb, $json${"ru": "Разворачивай кисть наружу по ходу подъёма. Локоть остаётся на месте, работает только предплечье.", "en": "Rotate the palm up as you lift. The elbow stays put; only the forearm moves."}$json$::jsonb, array['подъём гантелей на бицепс', 'бицепс с гантелями', 'dumbbell bicep curl']::text[], array['curl aux haltères', 'curl con mancuernas', 'db curl', 'dumbbell bicep curl', 'dumbbell curl', 'rosca alternada com halteres', 'бицепс с гантелями', 'подъем гантелей на бицепс', 'сгибание рук с гантелями']::text[], 'isolation', 'isolation', array['biceps']::text[], array['forearms']::text[], array['front_delts']::text[], array['dumbbell']::text[], false, false, 'reps', 10, 12, 60, array['gym', 'home']::text[], '/exercises/db_curl-1.webp', array['/exercises/db_curl-1.webp', '/exercises/db_curl-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('db_fly', $json${"ru": "Разводка гантелей лёжа", "en": "Dumbbell Fly", "pt": "Crucifixo com halteres", "es": "Aperturas con mancuernas", "fr": "Écarté aux haltères"}$json$::jsonb, $json${"ru": "Локти слегка согнуты и не меняют угол. Разводи до уровня плеч, чувствуя растяжение, и своди по той же дуге. Вес заметно меньше, чем в жиме.", "en": "Elbows softly bent at a fixed angle. Open to shoulder level into the stretch and return along the same arc. Much lighter than a press."}$json$::jsonb, array['разводка гантелей', 'разведение гантелей лёжа', 'dumbbell flye']::text[], array['aperturas con mancuernas', 'crucifixo com halteres', 'db fly', 'dumbbell fly', 'dumbbell flye', 'écarté aux haltères', 'разведение гантелей лежа', 'разводка гантелей', 'разводка гантелей лежа']::text[], 'isolation', 'isolation', array['chest']::text[], array['front_delts']::text[], '{}'::text[], array['dumbbell', 'bench']::text[], false, true, 'reps', 10, 15, 75, array['gym']::text[], '/exercises/db_fly-1.webp', array['/exercises/db_fly-1.webp', '/exercises/db_fly-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('db_front_raise', $json${"ru": "Подъём гантелей перед собой", "en": "Dumbbell Front Raise", "pt": "Elevação frontal com halteres", "es": "Elevaciones frontales", "fr": "Élévations frontales"}$json$::jsonb, $json${"ru": "Поднимай прямыми руками до уровня глаз, без раскачки. Передние дельты и так работают во всех жимах, поэтому объём здесь нужен небольшой.", "en": "Raise with straight arms to eye level without swinging. The front delts already work in every press, so keep the volume here modest."}$json$::jsonb, array['подъёмы гантелей стоя', 'фронтальные подъёмы', 'front raise']::text[], array['db front raise', 'dumbbell front raise', 'elevaciones frontales', 'elevação frontal com halteres', 'front raise', 'élévations frontales', 'подъем гантелей перед собой', 'подъемы гантелей стоя', 'фронтальные подъемы']::text[], 'isolation', 'isolation', array['front_delts']::text[], '{}'::text[], array['upper_chest', 'abs']::text[], array['dumbbell']::text[], false, false, 'reps', 12, 15, 60, array['gym', 'home']::text[], '/exercises/db_front_raise-1.webp', array['/exercises/db_front_raise-1.webp', '/exercises/db_front_raise-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
