  ('plank', $json${"ru": "Планка", "en": "Plank", "pt": "Prancha", "es": "Plancha", "fr": "Gainage planche"}$json$::jsonb, $json${"ru": "Локти под плечами, корпус прямой линией. Подверни таз и сожми ягодицы, поясница не провисает. Считай в секундах, а не в повторениях.", "en": "Elbows under the shoulders, body in one line. Tuck the pelvis and squeeze the glutes so the lower back does not sag. Counted in seconds, not reps."}$json$::jsonb, array['планка на локтях', 'передняя планка', 'front plank']::text[], array['front plank', 'gainage planche', 'plancha', 'plank', 'prancha', 'передняя планка', 'планка', 'планка на локтях']::text[], 'core', 'core', array['abs']::text[], array['obliques']::text[], array['front_delts', 'glutes', 'lower_back']::text[], array['bodyweight']::text[], false, false, 'seconds', 30, 60, 60, array['home', 'bodyweight', 'beginner_safe', 'timed']::text[], null, '{}'::text[], null, null),
