  ('pull_up', $json${"ru": "Подтягивания", "en": "Pull-Up", "pt": "Barra fixa", "es": "Dominadas", "fr": "Tractions"}$json$::jsonb, $json${"ru": "Хват прямой, чуть шире плеч. Начинай с опускания лопаток, тяни грудью к перекладине. Внизу распрямляй руки полностью, но не расслабляй плечи.", "en": "Overhand grip a bit wider than shoulders. Start by pulling the shoulder blades down, then drive the chest to the bar. Straighten the arms at the bottom without letting the shoulders go slack."}$json$::jsonb, array['подтягивания прямым хватом', 'подтягивание', 'pullup', 'pull ups']::text[], array['barra fixa', 'dominadas', 'pull up', 'pull ups', 'pullup', 'tractions', 'подтягивание', 'подтягивания', 'подтягивания прямым хватом']::text[], 'compound', 'vertical_pull', array['lats']::text[], array['biceps', 'upper_back']::text[], array['forearms', 'abs']::text[], array['pull_up_bar', 'bodyweight']::text[], false, false, 'reps', 5, 10, 150, array['gym', 'home', 'bodyweight']::text[], '/exercises/pull_up-1.webp', array['/exercises/pull_up-1.webp', '/exercises/pull_up-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('push_up', $json${"ru": "Отжимания от пола", "en": "Push-Up", "pt": "Flexão de braço", "es": "Flexiones", "fr": "Pompes"}$json$::jsonb, $json${"ru": "Корпус прямой линией от пяток до головы, таз не провисает. Локти назад под 45 градусов, грудь почти касается пола.", "en": "Body in one line from heels to head, hips not sagging. Elbows back at about 45 degrees, chest nearly touching the floor."}$json$::jsonb, array['отжимания', 'push ups', 'pushup']::text[], array['flexiones', 'flexão de braço', 'pompes', 'push up', 'push ups', 'pushup', 'отжимания', 'отжимания от пола']::text[], 'compound', 'horizontal_push', array['chest']::text[], array['triceps', 'front_delts']::text[], array['abs', 'obliques']::text[], array['bodyweight']::text[], false, false, 'reps', 10, 20, 60, array['home', 'bodyweight', 'beginner_safe']::text[], '/exercises/push_up-1.webp', array['/exercises/push_up-1.webp', '/exercises/push_up-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('rack_pull', $json${"ru": "Тяга с плинтов", "en": "Rack Pull", "pt": "Levantamento terra parcial", "es": "Peso muerto desde rack", "fr": "Rack pull"}$json$::jsonb, $json${"ru": "Штанга на упорах на уровне колена или чуть ниже. Короткая амплитуда позволяет работать с большим весом, чем в становой с пола.", "en": "Bar on the pins at or just below knee height. The short range lets you handle more than a deadlift from the floor."}$json$::jsonb, array['тяга с подставок', 'частичная становая']::text[], array['levantamento terra parcial', 'peso muerto desde rack', 'rack pull', 'тяга с плинтов', 'тяга с подставок', 'частичная становая']::text[], 'compound', 'hinge', array['lower_back', 'upper_back']::text[], array['glutes', 'traps']::text[], array['hamstrings', 'forearms', 'lats']::text[], array['barbell']::text[], false, false, 'reps', 4, 6, 180, array['gym', 'barbell_lift']::text[], null, '{}'::text[], null, null),
  ('reverse_crunch', $json${"ru": "Обратные скручивания", "en": "Reverse Crunch", "pt": "Abdominal invertido", "es": "Crunch inverso", "fr": "Crunch inversé"}$json$::jsonb, $json${"ru": "Колени над тазом, руки вдоль корпуса. Подкручивай таз к рёбрам, отрывая копчик от пола. Работает низ пресса, амплитуда маленькая.", "en": "Knees over the hips, arms by your sides. Curl the pelvis toward the ribs, lifting the tailbone off the floor. Small range, lower abs."}$json$::jsonb, array['обратные скручивания на пресс', 'подъём таза лёжа']::text[], array['abdominal invertido', 'crunch inverso', 'crunch inversé', 'reverse crunch', 'обратные скручивания', 'обратные скручивания на пресс', 'подъем таза лежа']::text[], 'core', 'core', array['abs']::text[], array['obliques']::text[], '{}'::text[], array['bodyweight']::text[], false, false, 'reps', 12, 20, 45, array['home', 'bodyweight', 'beginner_safe']::text[], '/exercises/reverse_crunch-1.webp', array['/exercises/reverse_crunch-1.webp', '/exercises/reverse_crunch-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('reverse_curl', $json${"ru": "Сгибание рук обратным хватом", "en": "Reverse Curl", "pt": "Rosca inversa", "es": "Curl inverso", "fr": "Curl inversé"}$json$::jsonb, $json${"ru": "Хват сверху, кисти зафиксированы прямо. Вес заметно меньше обычного подъёма, работают разгибатели предплечья и брахиорадиалис.", "en": "Overhand grip with the wrists held straight. Much lighter than a normal curl; the forearm extensors and brachioradialis do the work."}$json$::jsonb, array['обратный подъём на бицепс', 'обратные сгибания']::text[], array['curl inverso', 'curl inversé', 'reverse curl', 'rosca inversa', 'обратные сгибания', 'обратный подъем на бицепс', 'сгибание рук обратным хватом']::text[], 'isolation', 'isolation', array['forearms']::text[], array['biceps']::text[], '{}'::text[], array['ez_bar', 'barbell', 'dumbbell']::text[], false, false, 'reps', 12, 15, 60, array['gym']::text[], '/exercises/reverse_curl-1.webp', array['/exercises/reverse_curl-1.webp', '/exercises/reverse_curl-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('reverse_grip_bb_row', $json${"ru": "Тяга штанги обратным хватом", "en": "Reverse-Grip Barbell Row", "pt": "Remada curvada com pegada supinada", "es": "Remo con barra supino", "fr": "Rowing barre en supination"}$json$::jsonb, $json${"ru": "Хват снизу на ширине плеч, наклон меньше, чем в обычной тяге. Локти идут вдоль корпуса, широчайшие включаются сильнее верха спины.", "en": "Underhand grip at shoulder width, slightly more upright than a standard row. Elbows track along the torso and the lats take more than the upper back."}$json$::jsonb, array['тяга обратным хватом', 'yates row', 'reverse grip row']::text[], array['remada curvada com pegada supinada', 'remo con barra supino', 'reverse grip barbell row', 'reverse grip bb row', 'reverse grip row', 'rowing barre en supination', 'yates row', 'тяга обратным хватом', 'тяга штанги обратным хватом']::text[], 'compound', 'horizontal_pull', array['lats']::text[], array['upper_back', 'biceps']::text[], array['lower_back', 'forearms']::text[], array['barbell']::text[], false, false, 'reps', 8, 12, 120, array['gym', 'barbell_lift']::text[], '/exercises/reverse_grip_bb_row-1.webp', array['/exercises/reverse_grip_bb_row-1.webp', '/exercises/reverse_grip_bb_row-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('reverse_grip_pushdown', $json${"ru": "Разгибание на блоке обратным хватом", "en": "Reverse-Grip Triceps Pushdown", "pt": "Tríceps na polia com pegada supinada", "es": "Extensión de tríceps supino en polea", "fr": "Extension triceps en supination"}$json$::jsonb, $json${"ru": "Ладони вверх, локти прижаты. Смещает акцент на медиальную головку трицепса. Вес меньше, чем в прямом хвате.", "en": "Palms up, elbows pinned. Shifts the emphasis onto the medial head. Lighter than the overhand version."}$json$::jsonb, array['трицепс обратным хватом', 'разгибания обратным хватом']::text[], array['extension triceps en supination', 'extensión de tríceps supino en polea', 'reverse grip pushdown', 'reverse grip triceps pushdown', 'tríceps na polia com pegada supinada', 'разгибание на блоке обратным хватом', 'разгибания обратным хватом', 'трицепс обратным хватом']::text[], 'isolation', 'isolation', array['triceps']::text[], '{}'::text[], '{}'::text[], array['cable']::text[], false, false, 'reps', 12, 15, 60, array['gym']::text[], '/exercises/reverse_grip_pushdown-1.webp', array['/exercises/reverse_grip_pushdown-1.webp', '/exercises/reverse_grip_pushdown-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('reverse_lunge', $json${"ru": "Обратные выпады", "en": "Reverse Lunge", "pt": "Afundo para trás", "es": "Zancadas hacia atrás", "fr": "Fente arrière"}$json$::jsonb, $json${"ru": "Шаг назад, колено опускается под таз. Колено передней ноги почти не двигается вперёд, поэтому вариант мягче для коленей, чем выпад вперёд.", "en": "Step back and drop the rear knee under the hips. The front knee barely travels, which makes this kinder on the knees than a forward lunge."}$json$::jsonb, array['выпады назад', 'выпад назад с гантелями']::text[], array['afundo para trás', 'fente arrière', 'reverse lunge', 'zancadas hacia atrás', 'выпад назад с гантелями', 'выпады назад', 'обратные выпады']::text[], 'compound', 'lunge', array['glutes', 'quads']::text[], array['hamstrings', 'adductors']::text[], array['abs', 'calves']::text[], array['dumbbell', 'bodyweight']::text[], true, true, 'reps', 10, 12, 90, array['gym', 'home', 'back_friendly']::text[], null, '{}'::text[], null, null),
  ('reverse_pec_deck', $json${"ru": "Обратная бабочка", "en": "Reverse Pec Deck", "pt": "Crucifixo inverso na máquina", "es": "Contractor inverso", "fr": "Écarté inversé à la machine"}$json$::jsonb, $json${"ru": "Грудь прижата к подушке, руки почти прямые. Разводи назад по дуге до уровня плеч, не сводя лопатки сильно, иначе работу заберёт середина спины.", "en": "Chest on the pad, arms nearly straight. Sweep back to shoulder level without heavily squeezing the shoulder blades, or the mid back takes over."}$json$::jsonb, array['обратные разведения в тренажёре', 'задние дельты в тренажёре', 'reverse fly machine']::text[], array['contractor inverso', 'crucifixo inverso na máquina', 'reverse fly machine', 'reverse pec deck', 'écarté inversé à la machine', 'задние дельты в тренажере', 'обратная бабочка', 'обратные разведения в тренажере']::text[], 'isolation', 'isolation', array['rear_delts']::text[], array['upper_back']::text[], array['traps']::text[], array['pec_deck', 'machine']::text[], false, false, 'reps', 12, 20, 60, array['gym', 'machine_friendly', 'shoulder_health']::text[], null, '{}'::text[], null, null),
  ('romanian_deadlift', $json${"ru": "Румынская тяга", "en": "Romanian Deadlift", "pt": "Levantamento terra romeno", "es": "Peso muerto rumano", "fr": "Soulevé de terre roumain"}$json$::jsonb, $json${"ru": "Колени слегка согнуты и не сгибаются дальше. Отводи таз назад, штанга скользит по бедру, спина прямая. Опускай до натяжения задней поверхности, обычно чуть ниже колена.", "en": "Knees softly bent and staying there. Push the hips back with the bar grazing the thighs and a flat back. Lower until the hamstrings pull tight, usually just below the knee."}$json$::jsonb, array['румынка', 'тяга на прямых ногах', 'румынская тяга с гантелями', 'rdl', 'romanian dl']::text[], array['levantamento terra romeno', 'peso muerto rumano', 'rdl', 'romanian deadlift', 'romanian dl', 'soulevé de terre roumain', 'румынка', 'румынская тяга', 'румынская тяга с гантелями', 'тяга на прямых ногах']::text[], 'compound', 'hinge', array['hamstrings', 'glutes']::text[], array['lower_back']::text[], array['upper_back', 'forearms', 'adductors', 'lats']::text[], array['barbell', 'dumbbell']::text[], false, true, 'reps', 8, 12, 150, array['gym', 'barbell_lift']::text[], '/exercises/romanian_deadlift-1.webp', array['/exercises/romanian_deadlift-1.webp', '/exercises/romanian_deadlift-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('rowing_machine', $json${"ru": "Гребной тренажёр", "en": "Rowing Machine", "pt": "Remo ergométrico", "es": "Remo ergómetro", "fr": "Rameur"}$json$::jsonb, $json${"ru": "Порядок гребка: ноги, корпус, руки. Возврат в обратном порядке. Спина прямая, тянуть спиной вместо ног — самая частая ошибка.", "en": "Sequence: legs, then torso, then arms; reverse it on the recovery. Flat back. Pulling with the back instead of the legs is the classic mistake."}$json$::jsonb, array['гребля', 'гребной', 'rower', 'erg']::text[], array['erg', 'rameur', 'remo ergométrico', 'remo ergómetro', 'rower', 'rowing machine', 'гребля', 'гребной', 'гребной тренажер']::text[], 'cardio', 'cardio', array['full_body']::text[], array['upper_back', 'quads']::text[], array['lats', 'hamstrings', 'biceps']::text[], array['machine']::text[], false, false, 'minutes', 10, 30, 0, array['gym', 'cardio', 'timed']::text[], null, '{}'::text[], null, null),
  ('seated_bb_shoulder_press', $json${"ru": "Жим штанги сидя", "en": "Seated Barbell Shoulder Press", "pt": "Desenvolvimento com barra sentado", "es": "Press militar sentado", "fr": "Développé militaire assis"}$json$::jsonb, $json${"ru": "Спинка почти вертикальная, поясница прижата. Сидя корпус не помогает ногами, поэтому вес меньше, чем в жиме стоя.", "en": "Backrest near vertical, lower back on the pad. Seated you cannot help with the legs, so the weight drops below a standing press."}$json$::jsonb, array['жим штанги сидя на плечи', 'военный жим сидя', 'seated military press']::text[], array['desenvolvimento com barra sentado', 'développé militaire assis', 'press militar sentado', 'seated barbell shoulder press', 'seated bb shoulder press', 'seated military press', 'военный жим сидя', 'жим штанги сидя', 'жим штанги сидя на плечи']::text[], 'compound', 'vertical_push', array['front_delts']::text[], array['side_delts', 'triceps']::text[], array['upper_back', 'traps']::text[], array['barbell', 'bench']::text[], false, false, 'reps', 6, 10, 150, array['gym', 'barbell_lift']::text[], '/exercises/seated_bb_shoulder_press-1.webp', array['/exercises/seated_bb_shoulder_press-1.webp', '/exercises/seated_bb_shoulder_press-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
  ('seated_cable_row', $json${"ru": "Тяга горизонтального блока", "en": "Seated Cable Row", "pt": "Remada baixa sentado", "es": "Remo en polea baja", "fr": "Rowing à la poulie basse"}$json$::jsonb, $json${"ru": "Корпус вертикально, колени слегка согнуты. Тяни рукоять к низу живота, лопатки сводятся в конце. Не раскачивайся корпусом вперёд-назад.", "en": "Sit tall with soft knees. Pull the handle to the lower abdomen and let the shoulder blades come together at the end. Do not rock the torso back and forth."}$json$::jsonb, array['cable row', 'горизонтальная тяга', 'тяга к поясу сидя', 'тяга нижнего блока', 'тяга нижнего блока сидя']::text[], array['cable row', 'remada baixa sentado', 'remo en polea baja', 'rowing à la poulie basse', 'seated cable row', 'горизонтальная тяга', 'тяга горизонтального блока', 'тяга к поясу сидя', 'тяга нижнего блока', 'тяга нижнего блока сидя']::text[], 'compound', 'horizontal_pull', array['upper_back', 'lats']::text[], array['biceps', 'rear_delts']::text[], array['lower_back']::text[], array['seated_row', 'cable']::text[], false, false, 'reps', 10, 12, 90, array['gym', 'beginner_safe']::text[], '/exercises/seated_cable_row-1.webp', array['/exercises/seated_cable_row-1.webp', '/exercises/seated_cable_row-2.webp']::text[], 'CC BY-SA 4.0', 'Everkinetic (everkinetic.com), CC BY-SA 4.0'),
